def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    # Detect Slot 3: opponent defected on round 3 (n=2)
    if n >= 3 and opp[2] == 'D':
        if n in (3, 7, 13) or (n >= 10 and n % 5 == 0) or n >= 95:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Early retaliation
    if n == 1:
        return 'D' if opp[0] == 'D' else 'C'
    if n == 2:
        return 'D' if (opp[0] == 'D' or opp[1] == 'D') else 'C'

    # Endgame retaliation
    if n >= 95 and last_opp == 'D':
        return 'D'

    opp_c = opp.count('C')
    opp_d = n - opp_c

    if n >= 10:
        recent_opp = opp[-10:]
        recent_d = recent_opp.count('D')
        if recent_d >= 8:
            return 'D'
        if recent_d == 0 and last_opp == 'C':
            return 'C'

    if last_opp == 'D':
        if last_me == 'D':
            if n >= 4 and opp[-4:].count('D') >= 3:
                return 'D'
            if rng.random() < 0.35:
                return 'D'
            return 'C'
        else:
            if opp_d >= 10 and opp_c >= 10:
                return 'D'
            if rng.random() < 0.2:
                return 'D'
            return 'C'

    if last_opp == 'C':
        if last_me == 'D':
            return 'C'
        run_c = 0
        for a in reversed(opp):
            if a == 'C':
                run_c += 1
            else:
                break
        if run_c >= 5 and n >= 20:
            if rng.random() < 0.15:
                return 'D'
        return 'C'

    return 'C'
